import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine());
        int t = -1;
        int an = 0;
        String[] parts = sc.nextLine().split(" ");
        List<Integer> a = new ArrayList<>();
        for (int i = 0; i < parts.length; i++) {
            a.add(Integer.parseInt(parts[i]));
        }

        while (countOnes(a) > 0) {
            int onesCount = countOnes(a);
            int index = indexOfOne(a);
            an = Math.max(index + onesCount, an);
            a.remove(index);
        }

        System.out.println(Math.max(an, a.size()));
    }

    private static int countOnes(List<Integer> a) {
        int count = 0;
        for (int x : a) {
            if (x == 1) count++;
        }
        return count;
    }

    private static int indexOfOne(List<Integer> a) {
        for (int i = 0; i < a.size(); i++) {
            if (a.get(i) == 1) return i;
        }
        return -1;
    }
}

